const execute=promisify(execFile),hash=value=>createHash('sha256').update(value).digest('hex');
const nativeProbe=`#define _GNU_SOURCE
#include <sys/statvfs.h>
#include <sys/syscall.h>
#include <sys/mount.h>
#include <sched.h>
#include <fcntl.h>
#include <errno.h>
#include <stdio.h>
#include <unistd.h>
int main(void){if(access("/capacity-material/data/wait",F_OK)==0){FILE *ready=fopen("/capacity-material/data/ready","w");if(!ready)return 38;fputs("ready",ready);fclose(ready);for(int attempt=0;access("/capacity-material/data/release",F_OK);attempt++){if(attempt>20000)return 39;usleep(1000);}}int readable=open("/app/locked/sentinel",O_RDONLY);if(readable<0)return 40;close(readable);struct statvfs fs;if(statvfs("/",&fs)||!(fs.f_flag&ST_RDONLY))return 31;errno=0;if(open("/app/synthetic.mjs",O_WRONLY)>=0||errno!=EROFS)return 32;errno=0;if(unshare(CLONE_NEWUSER)!=-1||errno!=EPERM)return 33;errno=0;if(mount("none","/app",NULL,MS_BIND,NULL)!=-1||errno!=EPERM)return 34;char path[128];snprintf(path,sizeof(path),"/proc/%d/root",getppid());if(access(path,F_OK)==0)return 35;errno=0;if(fcntl(4,F_GETFD)!=-1||errno!=EBADF)return 36;FILE *file=fopen("/capacity-material/data/result","w");if(!file)return 37;fputs("readonly namespace fixture only",file);fclose(file);return 0;}`;
const fixtureBuilder=`import sys,pathlib,tarfile,io,gzip,hashlib,json,subprocess,base64
base=pathlib.Path(sys.argv[1]);binary=base/'probe';files={'usr/local/bin/node':binary.read_bytes(),'app/synthetic.mjs':b'synthetic-only','app/locked/sentinel':b'upper mode must allow access'}
for line in subprocess.run(['/usr/bin/ldd',str(binary)],capture_output=True,text=True,check=True).stdout.splitlines():
 for word in line.split():
  if word.startswith('/'):
   source=pathlib.Path(word);files[word.lstrip('/')]=source.read_bytes()
for name,text in json.loads((base/'extra-files.json').read_text()).items():files['app/'+name]=base64.b64decode(text['base64'],validate=True) if isinstance(text,dict) else text.encode()
if (base/'poison-public-grant').exists():files['capacity-public-origins.json']=(base/'poison-public-grant').read_bytes()
if (base/'safe.node').exists():files['app/safe.node']=(base/'safe.node').read_bytes()
files['app/ci/postgres-image-manifest.json']=json.dumps({'version':1,'revision':'a'*40,'files':{'synthetic.mjs':hashlib.sha256(files['app/synthetic.mjs']).hexdigest(),'locked/sentinel':hashlib.sha256(files['app/locked/sentinel']).hexdigest()}}).encode()
tar=io.BytesIO()
with tarfile.open(fileobj=tar,mode='w') as archive:
 for name,value in files.items():
  item=tarfile.TarInfo(name);item.size=len(value);item.mode=0o755 if name.startswith(('usr/','lib')) or name.endswith('.exe') else 0o666 if name=='app/synthetic.mjs' else 0o444;archive.addfile(item,io.BytesIO(value))
 for name,target in json.loads((base/'extra-links.json').read_text()).items():
  item=tarfile.TarInfo('app/'+name);item.type=tarfile.SYMTYPE;item.linkname=target;archive.addfile(item)
 item=tarfile.TarInfo('app/locked');item.type=tarfile.DIRTYPE;item.mode=0;archive.addfile(item)
 if len(sys.argv)>2 and sys.argv[2]=='shadow-material':
  item=tarfile.TarInfo('capacity-material/data');item.type=tarfile.SYMTYPE;item.linkname='/app';archive.addfile(item)
raw=tar.getvalue();packed=gzip.compress(raw,mtime=0);layer={'mediaType':'application/vnd.oci.image.layer.v1.tar+gzip','digest':'sha256:'+hashlib.sha256(packed).hexdigest(),'size':len(packed)}
layout=base/'oci';(layout/'blobs/sha256').mkdir(parents=True);(layout/'blobs/sha256'/layer['digest'][7:]).write_bytes(packed);
upper=io.BytesIO()
with tarfile.open(fileobj=upper,mode='w') as archive:
 item=tarfile.TarInfo('app/locked');item.type=tarfile.DIRTYPE;item.mode=0o755;archive.addfile(item)
upper_raw=upper.getvalue();upper_packed=gzip.compress(upper_raw,mtime=0);upper_digest=hashlib.sha256(upper_packed).hexdigest();(layout/'blobs/sha256'/upper_digest).write_bytes(upper_packed);upper_layer={'mediaType':'application/vnd.oci.image.layer.v1.tar+gzip','digest':'sha256:'+upper_digest,'size':len(upper_packed)}
all_layers=[layer,upper_layer];all_diff_ids=['sha256:'+hashlib.sha256(raw).hexdigest(),'sha256:'+hashlib.sha256(upper_raw).hexdigest()]
(base/'layer.json').write_text(json.dumps({'layers':all_layers,'diffIds':all_diff_ids}))
config={'os':'linux','architecture':'amd64','rootfs':{'type':'layers','diff_ids':all_diff_ids},'config':{'Labels':{'org.opencontainers.image.revision':'a'*40,'com.harbor.storage.postgres':'postgres-conversation-v2'}}}
def blob(value,kind):
 encoded=json.dumps(value).encode();digest=hashlib.sha256(encoded).hexdigest();(layout/'blobs/sha256'/digest).write_bytes(encoded);return {'mediaType':kind,'digest':'sha256:'+digest,'size':len(encoded)}
manifest=blob({'schemaVersion':2,'mediaType':'application/vnd.oci.image.manifest.v1+json','config':blob(config,'application/vnd.oci.image.config.v1+json'),'layers':all_layers},'application/vnd.oci.image.manifest.v1+json')
(layout/'index.json').write_text(json.dumps({'schemaVersion':2,'manifests':[manifest]}));(layout/'oci-layout').write_text(json.dumps({'imageLayoutVersion':'1.0.0'}));(base/'metadata.json').write_text(json.dumps({'manifestDigest':manifest['digest'],'revision':'a'*40,'layout':str(layout)}))
`;
async function untilExit(child,timeoutMs=15000){if(child.exitCode!==null)return child.exitCode;return new Promise((resolve,reject)=>{const timer=setTimeout(()=>reject(Error('runtime child exit timeout')),timeoutMs);child.once('exit',code=>{clearTimeout(timer);resolve(code);});});}

test('ordinary DTOs and synthetic layouts cannot acquire a trusted B artifact',async()=>{assert.throws(()=>capacityRuntimeArtifactBinding(Object.freeze({manifestDigest:'sha256:'+'a'.repeat(64),formalQualified:true})),/not_owned/);await assert.rejects(inspectCapacityRuntimeLayout({layout:'/not-created',manifestDigest:'latest',revision:'a'.repeat(40)}),/configuration/);});
async function fixture({shadowMaterial=false,nodeEntry=null,businessFiles={},businessLinks={},nativeAddon=false,harnessSources={},entryBranch=null,poisonPublicGrant=false}={}){
 const root=await mkdtemp(join(tmpdir(),'harbor-runtime-namespace-')),runtime=createOwnedRuntime();
 try{const entryDirectory=join(root,'tool'),directory=join(root,'namespace'),materials=join(root,'data');for(const path of [entryDirectory,directory,materials])await mkdir(path,{mode:0o700});if(nodeEntry===null){await writeFile(join(root,'probe.c'),nativeProbe);await execute('/usr/bin/cc',['-O2','-Wall','-Wextra','-Werror',join(root,'probe.c'),'-o',join(root,'probe')]);}else await fsPromises.copyFile(process.execPath,join(root,'probe'));await writeFile(join(root,'extra-files.json'),JSON.stringify(businessFiles));await writeFile(join(root,'extra-links.json'),JSON.stringify(businessLinks));if(nativeAddon){const source=join(root,'addon.c');await writeFile(source,'#include <stdint.h>\n#include <stdio.h>\n/* Minimal stable N-API v1 ABI declarations; no SDK install. */\ntypedef struct napi_env__* napi_env;typedef struct napi_value__* napi_value;extern int napi_create_int32(napi_env,int32_t,napi_value*);extern int napi_set_named_property(napi_env,napi_value,const char*,napi_value);extern int napi_throw_error(napi_env,const char*,const char*);\n__attribute__((visibility("default"))) napi_value napi_register_module_v1(napi_env env,napi_value exports){FILE *marker=fopen("/capacity-material/data/addon-executed","w");if(marker){fputs("executed",marker);fclose(marker);}'+(nativeAddon==='failing'?'napi_throw_error(env,0,"fixture initialization failed");return 0;':'')+'napi_value value;napi_create_int32(env,43,&value);napi_set_named_property(env,exports,"value",value);return exports;}\n__attribute__((visibility("default"))) int32_t node_api_module_get_api_version_v1(void){return 1;}\n');await execute('/usr/bin/cc',['-shared','-fPIC','-O2',source,'-o',join(root,'safe.node')]);if(nativeAddon==='overbudget')await fsPromises.truncate(join(root,'safe.node'),64*1024**2+1);}if(poisonPublicGrant)await writeFile(join(root,'poison-public-grant'),JSON.stringify({schema:'capacity-native-public-origins-v1',origins:['https://injected.invalid']}));await execute('/usr/bin/python3',['-c',fixtureBuilder,root,shadowMaterial?'shadow-material':'normal']);await buildCapacityRuntimeEntry({directory:entryDirectory});
 const harness=join(root,'harness'),relative=entryBranch==='remote-broker'?'tools/capacity/remote-broker-runtime.mjs':'tools/capacity/process-adapter.mjs';await mkdir(join(harness,'tools/capacity'),{recursive:true});const harnessBytes=Buffer.from(nodeEntry??'// Synthetic namespace fixture, never B proof.');await writeFile(join(harness,relative),harnessBytes);const harnessFiles={[relative]:hash(harnessBytes)};if(nodeEntry!==null){const path='tools/capacity/runtime-source-loader.mjs',content=await readFile(new URL('../'+path,import.meta.url));await writeFile(join(harness,path),content);harnessFiles[path]=hash(content);}
 for(const [path,content] of Object.entries(harnessSources)){await mkdir(join(harness,path,'..'),{recursive:true});await writeFile(join(harness,path),content);harnessFiles[path]=hash(content);}
 const structural=await inspectCapacityRuntimeLayout(JSON.parse(await readFile(join(root,'metadata.json'),'utf8')));assert.equal(structural.formalQualified,false);assert.throws(()=>capacityRuntimeArtifactBinding(structural),/not_owned/);
 const owner=await lstat(directory,{bigint:true}),data=await lstat(materials,{bigint:true}),layers=JSON.parse(await readFile(join(root,'layer.json'),'utf8'));
 const configuration={schema:'capacity-runtime-launch-v1',...(entryBranch?{entry:entryBranch}:{}),directory,owner:{device:String(owner.dev),inode:String(owner.ino)},tmpfsBytes:(nodeEntry===null?32:512)*1024**2,budget:{maxBytes:(nodeEntry===null?16:384)*1024**2,maxFiles:3000,timeoutSeconds:30},layout:join(root,'oci'),...layers,revision:'a'.repeat(40),harness:{directory:harness,files:harnessFiles},materials:[{name:'data',source:materials,device:String(data.dev),inode:String(data.ino)}]};
 return {root,runtime,entryDirectory,directory,materials,harness,relative,harnessBytes,configuration,start:()=>startCapacityRuntimeSandbox({entryDirectory,runtime,role:entryBranch==='remote-broker'?'helper':'gateway',configuration}),close:async()=>{await runtime.close();await rm(root,{recursive:true,force:true});}};
 }catch(error){await runtime.close();await rm(root,{recursive:true,force:true});throw error;}
}
async function applicationFixtureFiles(){
 const {fileURLToPath}=await import('node:url'),files={};for(const name of await fsPromises.readdir(new URL('..',import.meta.url)))if(name.endsWith('.mjs'))files[name]=await readFile(new URL('../'+name,import.meta.url),'utf8');
 async function collect(directory,relative){for(const item of await fsPromises.readdir(directory,{withFileTypes:true})){const at=join(directory,item.name),target=relative+'/'+item.name;if(item.isDirectory())await collect(at,target);else if(item.isFile()&&/\.(js|json|mjs|cjs|sql)$/.test(item.name))files[target]=await readFile(at,'utf8');}}
 for(const directory of ['node_modules','tools/capacity','ci','migrations'])await collect(fileURLToPath(new URL('../'+directory,import.meta.url)),directory);for(const [name,content] of Object.entries(files))if(name.startsWith('tools/capacity/'))files['ci/storage-operator-tools/'+name.slice('tools/capacity/'.length)]=content;for(const name of ['ci/postgres-deploy.py','ci/deploy-wrapper.py'])files[name]=await readFile(new URL('../'+name,import.meta.url),'utf8');files['package.json']=await readFile(new URL('../package.json',import.meta.url),'utf8');delete files['tools/capacity/process-adapter.mjs'];delete files['tools/capacity/runtime-source-loader.mjs'];delete files['ci/postgres-image-manifest.json'];return files;
}
async function until(read,predicate=value=>!!value,timeoutMs=10000){const deadline=performance.now()+timeoutMs;for(;;){const value=await read();if(predicate(value))return value;if(performance.now()>deadline)throw Error('runtime condition timeout');await new Promise(resolve=>setTimeout(resolve,5));}}
const real={skip:process.platform!=='linux'?'需Linux namespace':process.env.HARBOR_CAPACITY_NAMESPACE_TEST!=='1'?'需显式namespace实机开关，普通CI不冒充隔离正向':false,timeout:60000};
test('actual task-owned namespace copies fixture inodes, denies mutation/escape and releases mounts',real,async()=>{
 const f=await fixture();try{const child=await f.start();let errors='';child.stderr.on('data',chunk=>{errors+=chunk;});assert.equal(await untilExit(child),0,errors);assert.equal(await readFile(join(f.materials,'result'),'utf8'),'readonly namespace fixture only');assert.deepEqual(await (await import('node:fs/promises')).readdir(f.directory),[]);}finally{await f.close();}
});
test('source replacement cannot change the already loaded readonly private namespace',real,async()=>{
 const f=await fixture();try{await writeFile(join(f.materials,'wait'),'wait');const child=await f.start();await until(async()=>readFile(join(f.materials,'ready'),'utf8').catch(()=>null));await writeFile(join(f.root,'probe'),'changed external input');await writeFile(join(f.harness,f.relative),'changed external input');const copied='/proc/'+child.pid+'/root/app/'+f.relative;assert.deepEqual(await readFile(copied),f.harnessBytes);await writeFile(join(f.materials,'release'),'release');assert.equal(await untilExit(child),0);}finally{await f.close();}
});
test('stopped namespace leader is resumed and terminated without leaving its mounts or helper',real,async()=>{
 const f=await fixture();try{await writeFile(join(f.materials,'wait'),'wait');const child=await f.start();await until(async()=>readFile(join(f.materials,'ready'),'utf8').catch(()=>null));process.kill(child.pid,'SIGSTOP');await terminateOwnedCapacityChild(f.runtime,child,{graceMs:1000});assert.notEqual(child.signalCode,null);assert.deepEqual(await (await import('node:fs/promises')).readdir(f.directory),[]);}finally{await f.close();}
});

for(const source of ['harness','native'])test('FIFO replacement of '+source+' refuses startup without blocking',real,async()=>{
 const f=await fixture();try{let child;if(source==='harness'){const path=join(f.harness,f.relative);await (await import('node:fs/promises')).unlink(path);await execute('/usr/bin/mkfifo',[path]);child=await f.start();}else{child=await f.start();const path=join(f.entryDirectory,'entry');await (await import('node:fs/promises')).unlink(path);await execute('/usr/bin/mkfifo',[path]);}let errors='';child.stderr.on('data',chunk=>{errors+=chunk;});assert.equal(await untilExit(child,3000),126);assert.match(errors,/capacity_runtime_copy_source_type/);assert.deepEqual(await (await import('node:fs/promises')).readdir(f.directory),[]);}finally{await f.close();}
});

